create table if not exists public.neena_admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create table if not exists public.neena_site_content (id text primary key, content jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
insert into public.neena_site_content(id,content) values('neena','{}'::jsonb) on conflict(id) do nothing;
alter table public.neena_admin_users enable row level security;
alter table public.neena_site_content enable row level security;
create policy "Approved editors read own record" on public.neena_admin_users for select to authenticated using (user_id = auth.uid());
create policy "Anyone reads published site" on public.neena_site_content for select to anon,authenticated using (id='neena');
create policy "Approved editors update site" on public.neena_site_content for update to authenticated using (id='neena' and exists(select 1 from public.neena_admin_users where user_id=auth.uid())) with check (id='neena' and exists(select 1 from public.neena_admin_users where user_id=auth.uid()));
grant select on public.neena_admin_users to authenticated;
grant select on public.neena_site_content to anon, authenticated;
grant update(content, updated_at) on public.neena_site_content to authenticated;
